"""Select UniTool's Android-permission-aware libusb for PyUSB.

This runs during Python startup. It deliberately disables PyUSB's normal
system-library lookup when UniTool supplies an explicit absolute library path.
"""
import os


def _configure_pyusb_libusb():
    library_path = (
        os.environ.get("UNITOOL_LIBUSB_PATH")
        or os.environ.get("PYUSB_LIBUSB_PATH")
    )
    if not library_path:
        return

    library_path = os.path.abspath(library_path)
    try:
        import usb.backend.libusb1 as libusb1
    except ImportError:
        # PyUSB may be installed later with pip. sitecustomize runs again on
        # every new interpreter process, so the patch is applied then.
        return

    original_get_backend = libusb1.get_backend
    if getattr(original_get_backend, "_unitool_configured", False):
        return

    def get_backend(find_library=None):
        # Preserve explicit callers' loader choices. For PyUSB's default
        # discovery, force the exact library bundled with this APK.
        if find_library is None:
            find_library = lambda _name: library_path
        return original_get_backend(find_library=find_library)

    get_backend._unitool_configured = True
    get_backend._unitool_library_path = library_path
    libusb1.get_backend = get_backend


_configure_pyusb_libusb()
